BEGIN;
DROP INDEX IF EXISTS public.block_relations_blocked;
DROP INDEX IF EXISTS public.follows_followee;
DROP INDEX IF EXISTS public.friend_requests_recipient;
DROP INDEX IF EXISTS public.friend_requests_requester;
DROP INDEX IF EXISTS public.friendships_high;
DROP INDEX IF EXISTS public.login_sessions_token_hash;
DROP INDEX IF EXISTS public.login_sessions_user_id;
DROP INDEX IF EXISTS public.notifications_created_at;
DROP INDEX IF EXISTS public.posting_windows_created_at;
DROP INDEX IF EXISTS public.posts_image_id;
DROP INDEX IF EXISTS public.realmojis_image_id;
DROP INDEX IF EXISTS public.users_created_at;
DROP INDEX IF EXISTS public.users_username_uniq;
CREATE INDEX posts_posting_window_id ON public.posts USING btree (posting_window_id);
ALTER TABLE ONLY public.administrator_sessions ADD CONSTRAINT administrator_sessions_administrator_id_fkey FOREIGN KEY (administrator_id) REFERENCES public.administrators(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.block_relations ADD CONSTRAINT block_relations_blocked_id_fkey FOREIGN KEY (blocked_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.block_relations ADD CONSTRAINT block_relations_blocker_id_fkey FOREIGN KEY (blocker_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.comments ADD CONSTRAINT comments_author_id_fkey FOREIGN KEY (author_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.comments ADD CONSTRAINT comments_post_id_fkey FOREIGN KEY (post_id) REFERENCES public.posts(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.follows ADD CONSTRAINT follows_followee_id_fkey FOREIGN KEY (followee_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.follows ADD CONSTRAINT follows_follower_id_fkey FOREIGN KEY (follower_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.friend_requests ADD CONSTRAINT friend_requests_recipient_id_fkey FOREIGN KEY (recipient_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.friend_requests ADD CONSTRAINT friend_requests_requester_id_fkey FOREIGN KEY (requester_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.friendships ADD CONSTRAINT friendships_user_high_id_fkey FOREIGN KEY (user_high_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.friendships ADD CONSTRAINT friendships_user_low_id_fkey FOREIGN KEY (user_low_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.image_objects ADD CONSTRAINT image_objects_owner_fk FOREIGN KEY (owner_user_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.login_sessions ADD CONSTRAINT login_sessions_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.notifications ADD CONSTRAINT notifications_posting_window_id_fkey FOREIGN KEY (posting_window_id) REFERENCES public.posting_windows(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.notifications ADD CONSTRAINT notifications_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.posts ADD CONSTRAINT posts_author_id_fkey FOREIGN KEY (author_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.posts ADD CONSTRAINT posts_image_id_fkey FOREIGN KEY (image_id) REFERENCES public.image_objects(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.posts ADD CONSTRAINT posts_posting_window_id_fkey FOREIGN KEY (posting_window_id) REFERENCES public.posting_windows(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.realmojis ADD CONSTRAINT realmojis_image_id_fkey FOREIGN KEY (image_id) REFERENCES public.image_objects(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.realmojis ADD CONSTRAINT realmojis_post_id_fkey FOREIGN KEY (post_id) REFERENCES public.posts(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.realmojis ADD CONSTRAINT realmojis_reactor_id_fkey FOREIGN KEY (reactor_id) REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.users ADD CONSTRAINT users_profile_image_id_fkey FOREIGN KEY (profile_image_id) REFERENCES public.image_objects(id) ON DELETE RESTRICT;
ALTER TABLE ONLY public.image_objects ALTER COLUMN data SET STORAGE EXTENDED;
DROP EXTENSION IF EXISTS pg_stat_statements;
COMMIT;
ANALYZE;
